Method.Implementation:
	 try{
		do ##super()
		$$$TRACE("OnInit Connect to " _ ..ApplicationAddress)
		set ..objCdrTuxService = ##class(org.ihc.itf.cdr.ClinActionInfoByEventID).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService, ..LogDirectory _"/" _$$$JobConfigName _".log", $$$ConfigTrace($$$JobConfigName))
     	set status = ..CheckObject()
	}catch err{
		$$$LOGERROR("Exception while Creating Tuxedo Service: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
	    set status=$$$ERROR(" Exception while initializing Tuxedo Service: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)
	}

	quit status

	 #dim status as %Status
	 set status = $$$OK

	 try {	
	 	if (..CheckObject() '= $$$OK) {
		 	$$$TRACE("**** Object does not exists ****")
		 	// Try to re intialize
		 	set result = ..OnInit()
			if (result '= $$$OK)
			{
				set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Op-Cdr-CHECKMMI", "Retrieve immunization event id failed. EMPI#: " _pRequest.StringValue_ " ; Reason: " _ result)						
				return status
			}
	 	}

		$$$TRACE("Object name: " _ ..objCdrTuxService.%ClassName(1))
		$$$TRACE("Request Event ID : " _ pRequest.StringValue)
		set pResponse = ##class(Ens.StringResponse).%New()  
 		set pResponse.StringValue = "" 
        if ($LENGTH(pRequest.StringValue)>1) {
		  set result = ..objCdrTuxService.ClinActionInfoByEventID(pRequest.StringValue)	
		  if ($LENGTH(result) > 10) {	
 		    set pResponse.StringValue = result 
 		    $$$TRACE("**** After ClinActionInfoByEventID Call ****"_pResponse.StringValue)	
		  }
		  else{ 		
	 		$$$TRACE("Event ID: "_pRequest.StringValue_" does not have action info data in CDR.")
 		  }
        }
	 } catch err {	
		    Set status = ..ExceptionHandler(err, "OnMessage")
	 }	    

	 $$$TRACE("OnMessage status: " _ status)	
	 return status
